from datetime import date

CAL = {"WKDY": ([1, 1, 1, 1, 1, 0, 0], date(2026, 6, 1), date(2026, 8, 31))}
EXC = {("WKDY", date(2026, 7, 3)): 2}

def service_active(service_id, d):
    exc = EXC.get((service_id, d))
    if exc == 1:
        return True          # added for this date
    if exc == 2:
        return False         # removed for this date
    days, start, end = CAL[service_id]
    return start <= d <= end and days[d.weekday()] == 1

for d in [date(2026, 7, 2), date(2026, 7, 3), date(2026, 7, 4), date(2026, 7, 6)]:
    print(d, service_active("WKDY", d))
# 2026-07-02 True   (Thursday)
# 2026-07-03 False  (Friday, removed)
# 2026-07-04 False  (Saturday, not in the weekly pattern)
# 2026-07-06 True   (Monday)

def predict(stop_times, updates):
    # stop_times: [(seq, sched_sec)] for one trip instance
    # updates: {seq: delay_sec or "NO_DATA" or "SKIPPED"}
    out, delay = {}, None
    for seq, sched in stop_times:
        u = updates.get(seq)
        if u == "NO_DATA":
            delay = None
        elif u == "SKIPPED":
            out[seq] = "skip"
            continue
        elif u is not None:
            delay = u
        out[seq] = None if delay is None else sched + delay
    return out

T1 = [(1, 28800), (2, 29160), (3, 29580), (4, 30060), (5, 30600)]
print(predict(T1, {3: 120}))

import time, requests
from google.transit import gtfs_realtime_pb2 as rt

URL = "https://example.org/gtfs-rt/tripupdates"   # your agency's feed
last_modified, last_ts, state = None, 0, {}

while True:
    headers = {"If-Modified-Since": last_modified} if last_modified else {}
    r = requests.get(URL, headers=headers, timeout=10)
    if r.status_code == 200:
        feed = rt.FeedMessage()
        feed.ParseFromString(r.content)
        ts = feed.header.timestamp
        if ts >= last_ts:                       # never go backwards
            last_ts = ts
            last_modified = r.headers.get("Last-Modified")
            state = {}                          # FULL_DATASET: replace, do not merge
            for e in feed.entity:
                if e.HasField("trip_update"):
                    d = e.trip_update.trip
                    state[(d.trip_id, d.start_date)] = e.trip_update
    time.sleep(30)
